async function authorized(request: Request) {
  const env = await runtime(); if (!env.DB || !env.BUCKET) throw new SequentialCommandError("SEQUENTIAL_RUNTIME_UNAVAILABLE", 503, "Canonical D1 and R2 are required");
  let user = await getChatGPTUser();
  if (!user && await secretMatches(request.headers.get("x-sequential-executor-token") || "", env.SEQUENTIAL_EXECUTOR_TOKEN || "")) { const email = clean(env.FACTORY_AUTOMATION_ACTOR_EMAIL); if (email) user = { email, displayName: clean(env.FACTORY_AUTOMATION_ACTOR_NAME) || email, fullName: null }; }
  const requestedAction = request.method === "POST" ? clean(((await request.clone().json().catch(() => null)) as Row | null)?.action).toUpperCase() : "";
  if (!user && requestedAction === "AUDIT_GOLDEN_AUDIO_PERCEPTUAL" && await secretMatches(request.headers.get("x-perceptual-qa-executor-token") || "", env.PERCEPTUAL_QA_EXECUTOR_TOKEN || "")) { const email = clean(env.FACTORY_AUTOMATION_ACTOR_EMAIL); if (email) user = { email, displayName: clean(env.FACTORY_AUTOMATION_ACTOR_NAME) || email, fullName: null }; }
  if (!user) throw new SequentialCommandError("SIWC_AUTHENTICATION_REQUIRED", 401, "Owner authentication is required");
  const allowlist = new Set(clean(env.FACTORY_EXPERT_EMAILS).split(",").map((email) => email.trim().toLowerCase()).filter(Boolean));
  if (!allowlist.has(user.email.toLowerCase())) throw new SequentialCommandError("CHANNEL_OWNER_AUTHORIZATION_REQUIRED", 403, "This identity cannot execute Video Excellence production");
  return { env, actor: user.email.toLowerCase() };
}

async function context(db: DB) {
  const program = await first(db, "SELECT * FROM v7_sequential_programs WHERE channel_id=? AND contract_version=? AND lifecycle_state='ACTIVE' LIMIT 1", CHANNEL_ID, CONTRACT);
  const queue = program ? await first(db, "SELECT * FROM v7_sequential_queue WHERE program_id=? AND sequence=1 AND active=1 LIMIT 1", program.id) : null;
  if (!program || !queue) throw new SequentialCommandError("VIDEO_01_NOT_ACTIVE", 409, "Video #1 must own the sequential queue");
  return { program, queue };
}

async function requireFirstPassOperation(env: Env, operation: string, stageKey: string) {
  const ctx = await context(env.DB!);
  const capability = await assertFirstPassCapabilityEligibility(env.DB!, {
    operation,
    stageKey,
    programId: clean(ctx.program.id),
    queueId: clean(ctx.queue.id),
  });
  return { ctx, capability };
}

async function guardedQualityDispatch<T>(request: Request, env: Env, actor: string, input: { operation: string; stageKey: string; providers: string[]; requestedProviderRequests: number; rightsState: string }, execute: (integrity: DispatchAuthorization) => Promise<T>) {
  const idempotencyKey = clean(request.headers.get("idempotency-key"));
  if (!/^[A-Za-z0-9._:-]{16,200}$/.test(idempotencyKey)) throw new ProductionIntegrityError("IDEMPOTENCY_KEY_INVALID", 400, "A stable Idempotency-Key is required for quality dispatch");
  const fence = readFencingHeaders(request), { ctx, capability } = await requireFirstPassOperation(env, input.operation, input.stageKey);
  const integrity = await authorizeProductionDispatch(env.DB!, { programId: clean(ctx.program.id), queueId: clean(ctx.queue.id), stageKey: input.stageKey, budgetScope: "GOLDEN", operation: input.operation, actor, providers: input.providers, idempotencyKey, intent: { operation: input.operation, stageKey: input.stageKey, standardVersion: VIDEO_QUALITY_STANDARD_VERSION }, ...fence, qualificationIds: capability.qualificationIds, requestedProviderRequests: input.requestedProviderRequests, rightsState: input.rightsState, allowedRightsStates: [input.rightsState], safetyRequired: true });
  await markDispatchStarted(env.DB!, integrity.reservationId);
  try {
    const result = await execute(integrity);
    await assertCommandLease(env.DB!, { programId: clean(ctx.program.id), queueId: clean(ctx.queue.id), stageKey: input.stageKey, ...fence });
    const actual = await first(env.DB!, "SELECT COUNT(*) requests,COALESCE(SUM(cost_usd),0) spend FROM v7_sequential_provider_requests WHERE reservation_id=?", integrity.reservationId);
    await settleProductionDispatch(env.DB!, { reservationId: integrity.reservationId, traceId: integrity.traceId, actualProviderRequests: Number(actual?.requests || 0), actualSpendUsd: Number(actual?.spend || 0) });
    return result;
  } catch (error) {
    const actual = await first(env.DB!, "SELECT COUNT(*) requests,COALESCE(SUM(cost_usd),0) spend FROM v7_sequential_provider_requests WHERE reservation_id=?", integrity.reservationId);
    await settleProductionDispatch(env.DB!, { reservationId: integrity.reservationId, traceId: integrity.traceId, actualProviderRequests: Number(actual?.requests || 0), actualSpendUsd: Number(actual?.spend || 0), failureCode: error instanceof Error ? error.message : "QUALITY_DISPATCH_FAILED" });
    throw error;
  }
}

async function approvedPlan(db: DB, queueId: unknown) {
  const plan = await first(db, "SELECT * FROM v7_sequential_budget_plans WHERE queue_id=? AND lifecycle_state='APPROVED' ORDER BY version DESC LIMIT 1", queueId);
  if (!plan || !parseJson<string[]>(plan.stage_scope_json, []).includes("GOLDEN")) throw new SequentialCommandError("APPROVED_GOLDEN_PLAN_REQUIRED", 409, "The latest cost-rights plan must authorize GOLDEN production");
  const actual = await first(db, "SELECT COALESCE(SUM(cost_usd),0) spend,COUNT(*) requests FROM v7_sequential_provider_requests WHERE queue_id=? AND lifecycle_state IN ('COMPLETED','FAILED')", queueId);
  if (Number(actual?.spend || 0) >= Number(plan.max_spend_usd || 0) || Number(actual?.requests || 0) >= Number(plan.max_provider_requests || 0)) throw new SequentialCommandError("QUALITY_PLAN_EXHAUSTED", 409, "The approved cost or request ceiling has been reached");
  return plan;
}

async function store(env: Env, key: string, bytes: Uint8Array, contentType: string) {
  const hash = await sha256(bytes); await env.BUCKET!.put(key, bytes, { httpMetadata: { contentType }, customMetadata: { sha256: hash, standardVersion: VIDEO_QUALITY_STANDARD_VERSION } });
  const object = await env.BUCKET!.get(key); if (!object) throw new SequentialCommandError("QUALITY_ASSET_READBACK_FAILED", 503, "Golden-sequence asset read-back failed");
  const readback = new Uint8Array(await object.arrayBuffer()); if (await sha256(readback) !== hash) throw new SequentialCommandError("QUALITY_ASSET_HASH_MISMATCH", 503, "Golden-sequence asset checksum mismatch");
  return { sha256: hash, byteSize: readback.byteLength };
}

