  await env.DB!.prepare("UPDATE v7_golden_sequences SET lifecycle_state=?,quality_json=?,evidence_hash=?,updated_at=? WHERE id=?").bind(pass ? "AUDIT_PASS_PLAYBACK_REQUIRED" : "REPAIR_REQUIRED", json({ ...parseJson<Row>(golden.quality_json, {}), masterIndependentAudit: result, masterProviderResponseId: payload.id, masterAuditUsage: usage }), auditHash, now(), golden.id).run();
