export async function GET(request: Request) {
  try { const env = await runtime(); if (!env.DB || !env.BUCKET) throw new Error("Canonical runtime unavailable"); const url = new URL(request.url), assetId = url.searchParams.get("asset"); if (assetId) { const asset = await first(env.DB, "SELECT * FROM v7_golden_sequence_assets WHERE id=? LIMIT 1", assetId); if (!asset) return new Response("Not found", { status: 404 }); return await serveGoldenAsset(env, request, asset); } const ctx = await context(env.DB), [standards, evidence, golden] = await Promise.all([rows(env.DB, "SELECT id,scope,scope_key,enforcement_level,metric,threshold_or_range,owning_stage,failure_action FROM v7_video_quality_standards WHERE standard_version=? AND active=1 ORDER BY scope,id", VIDEO_QUALITY_STANDARD_VERSION), rows(env.DB, "SELECT standard_id,lifecycle_state,evidence_kind,evidence_hash,measured_value_json,findings_json,created_at FROM v7_video_quality_evidence WHERE queue_id=? AND standard_version=? ORDER BY created_at", ctx.queue.id, VIDEO_QUALITY_STANDARD_VERSION), first(env.DB, "SELECT * FROM v7_golden_sequences WHERE queue_id=? AND standard_version=? ORDER BY revision DESC LIMIT 1", ctx.queue.id, VIDEO_QUALITY_STANDARD_VERSION)]); const assets = golden ? await rows(env.DB, "SELECT id,role,shot_id,temporal_state,mime_type,byte_size,sha256,metadata_json FROM v7_golden_sequence_assets WHERE golden_sequence_id=? ORDER BY shot_id,temporal_state,role", golden.id) : [], masterJob = golden ? await first(env.DB, "SELECT lifecycle_state,master_asset_id,probe_json,scan_json,playback_json,error_code FROM v7_golden_master_jobs WHERE golden_sequence_id=? AND revision=? LIMIT 1", golden.id, golden.revision) : null; return Response.json({ standardVersion: VIDEO_QUALITY_STANDARD_VERSION, standards, evidence, golden: golden ? { id: golden.id, revision: golden.revision, state: golden.lifecycle_state, durationSeconds: golden.duration_seconds, manifest: parseJson(golden.manifest_json, {}), quality: parseJson(golden.quality_json, {}), masterJob: masterJob ? { state: masterJob.lifecycle_state, masterAssetId: masterJob.master_asset_id, probe: parseJson(masterJob.probe_json, null), scan: parseJson(masterJob.scan_json, null), playback: parseJson(masterJob.playback_json, null), errorCode: masterJob.error_code } : null, assets: assets.map((asset) => ({ ...asset, url: `/api/factory/sequential-production/quality?asset=${encodeURIComponent(clean(asset.id))}`, metadata: parseJson(asset.metadata_json, {}) })) } : null }, { headers: NO_STORE }); } catch (error) { return Response.json({ error: { code: "VIDEO_QUALITY_PROJECTION_UNAVAILABLE", message: error instanceof Error ? error.message : "Quality projection unavailable" } }, { status: 503, headers: NO_STORE }); }
}

export async function POST(request: Request) {
  try {
    const { env, actor } = await authorized(request), body = await request.json().catch(() => null) as Row | null, action = clean(body?.action).toUpperCase();
    if (action === "CREATE_GOLDEN_PLAN") {
      await requireFirstPassOperation(env, "RUN_STAGE_09_BATCH", "09");
      await requireFirstPassOperation(env, "PRODUCE_GOLDEN_AUDIO", "10");
      return Response.json(await createGoldenPlan(env), { status: 201, headers: NO_STORE });
    }
    if (action === "PRODUCE_GOLDEN_VISUALS") {
      await requireFirstPassOperation(env, "RUN_STAGE_09_BATCH", "09");
      return Response.json(await produceGoldenVisuals(env, actor), { status: 201, headers: NO_STORE });
    }
    if (["PRODUCE_GOLDEN_AUDIO", "REASSESS_GOLDEN_AUDIO", "PROMOTE_VERIFIED_GOLDEN_AUDIO"].includes(action)) {
      await requireFirstPassOperation(env, "PRODUCE_GOLDEN_AUDIO", "10");
      if (action === "PRODUCE_GOLDEN_AUDIO") return Response.json(await guardedQualityDispatch(request, env, actor, { operation: "PRODUCE_GOLDEN_AUDIO", stageKey: "10", providers: ["ELEVENLABS", "OPENAI"], requestedProviderRequests: 8, rightsState: "COMMERCIAL_LICENSE_VERIFIED" }, (integrity) => produceGoldenAudio(env, actor, integrity)), { status: 201, headers: NO_STORE });
      if (action === "REASSESS_GOLDEN_AUDIO") return Response.json(await reassessGoldenAudio(env, actor), { status: 201, headers: NO_STORE });
      return Response.json(await promoteVerifiedGoldenAudio(env, actor), { status: 201, headers: NO_STORE });
    }
    if (action === "REQUEST_GOLDEN_MASTER_RENDER") {
      await requireFirstPassOperation(env, "REQUEST_GOLDEN_MASTER_RENDER", "13");
      return Response.json(await requestGoldenMasterRender(env), { status: 201, headers: NO_STORE });
    }
    if (action === "AUDIT_GOLDEN_SEQUENCE") {
      await requireFirstPassOperation(env, "GOLDEN_MASTER_INDEPENDENT_AUDIT", "14");
      return Response.json(await guardedQualityDispatch(request, env, actor, { operation: "GOLDEN_MASTER_INDEPENDENT_AUDIT", stageKey: "14", providers: ["OPENAI"], requestedProviderRequests: 1, rightsState: "CHANNEL_OWNED_AUDIT_INPUT" }, (integrity) => auditGolden(env, actor, integrity)), { status: 201, headers: NO_STORE });
    }
    if (action === "AUDIT_GOLDEN_AUDIO_PERCEPTUAL") {
      await requireFirstPassOperation(env, "GOLDEN_AUDIO_PERCEPTUAL_AUDIT", "14");
      return Response.json(await guardedQualityDispatch(request, env, actor, { operation: "GOLDEN_AUDIO_PERCEPTUAL_AUDIT", stageKey: "14", providers: ["OPENAI"], requestedProviderRequests: 1, rightsState: "CHANNEL_OWNED_AUDIT_INPUT" }, (integrity) => auditGoldenAudioPerceptual(env, actor, integrity)), { status: 201, headers: NO_STORE });
    }
    if (action === "SUBMIT_GOLDEN_HUMAN_PLAYBACK") return Response.json(await submitGoldenHumanPlayback(env, actor, body || {}), { status: 201, headers: NO_STORE });
    if (action === "RECONCILE_GOLDEN_PASS_EVIDENCE") return Response.json(await reconcileGoldenPassEvidence(env, actor), { status: 201, headers: NO_STORE });
    return Response.json({ error: { code: "VIDEO_QUALITY_ACTION_INVALID", message: "Use the typed golden component, master-render, independent-audit, perceptual-audio or human-playback commands" } }, { status: 400, headers: NO_STORE });
  } catch (error) {
    if (error instanceof ProductionIntegrityError) return Response.json({ error: { code: error.code, message: error.message, reasons: error.reasons }, providerRequests: 0, spendUsd: 0 }, { status: error.status, headers: NO_STORE });
    if (error instanceof FirstPassCapabilityError) return Response.json({ error: { code: error.code, message: error.message, gaps: error.gaps }, providerRequests: 0, spendUsd: 0 }, { status: error.status, headers: NO_STORE });
    if (error instanceof SequentialCommandError) return Response.json({ error: { code: error.code, message: error.message } }, { status: error.status, headers: NO_STORE });
    return Response.json({ error: { code: "VIDEO_QUALITY_EXECUTION_FAILED", message: error instanceof Error ? error.message : "Video quality execution failed" } }, { status: 503, headers: NO_STORE });
  }
}

export async function PUT(request: Request) {
  try { const { env, actor } = await authorized(request), url = new URL(request.url), jobId = clean(url.searchParams.get("job")), kind = clean(url.searchParams.get("kind")); if (!jobId) throw new SequentialCommandError("GOLDEN_MASTER_JOB_REQUIRED", 400, "A golden master job is required"); if (kind === "master") return Response.json(await completeGoldenMaster(env, request, jobId, actor), { status: 201, headers: NO_STORE }); if (kind === "contact-sheet") return Response.json(await completeGoldenContactSheet(env, request, jobId, Number(url.searchParams.get("index")), actor), { status: 201, headers: NO_STORE }); throw new SequentialCommandError("GOLDEN_MASTER_UPLOAD_KIND_INVALID", 400, "Use master or contact-sheet upload kind"); } catch (error) { if (error instanceof SequentialCommandError) return Response.json({ error: { code: error.code, message: error.message } }, { status: error.status, headers: NO_STORE }); return Response.json({ error: { code: "GOLDEN_MASTER_UPLOAD_FAILED", message: error instanceof Error ? error.message : "Golden master upload failed" } }, { status: 503, headers: NO_STORE }); }
}
